import React, { useState } from "react";
import {
  AppBar,
  Toolbar,
  IconButton,
  Drawer,
  List,
  ListItem,
  ListItemText,
  Box,
  useMediaQuery,
  useTheme,
  Tabs,
  Tab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Typography,
  Rating,
  TextField,
  Button,
  Avatar,
  Chip,
} from "@mui/material";
import { GiHamburgerMenu } from "react-icons/gi";
import { FaTableTennis, FaCloudUploadAlt } from "react-icons/fa";
import { Close } from "@mui/icons-material";
import CustomButton from "../Components/CustomButton";
import { GoogleLogin } from '@react-oauth/google';
import { jwtDecode } from "jwt-decode";

const NavBar = () => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [currentTab, setCurrentTab] = useState(0);
  const [reviewDialogOpen, setReviewDialogOpen] = useState(false);
  const [user, setUser] = useState(null);
  const [reviewData, setReviewData] = useState({
    name: "",
    rating: 0,
    comment: "",
    photo: null,
    photoPreview: null,
  });
  const [showGoogleLogin, setShowGoogleLogin] = useState(false);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  const menuItems = ["Home", "About", "Testimonials", "Gallery and Awards"];

  const handleDrawerToggle = () => {
    setDrawerOpen(!drawerOpen);
  };

  const handleTabChange = (event, newValue) => {
    setCurrentTab(newValue);
    console.log("Navigating to:", menuItems[newValue]);
  };

  const handleMobileMenuItemClick = (index) => {
    setCurrentTab(index);
    setDrawerOpen(false);
    console.log("Navigating to:", menuItems[index]);
  };

  // Handle Add Review Button Click
  const handleAddReviewClick = () => {
    if (user) {
      // User is already authenticated, open dialog directly
      setReviewDialogOpen(true);
    } else {
      // User is not authenticated, show Google Login
      setShowGoogleLogin(true);
    }
  };

  // Google Auth Success Handler
  const handleGoogleSuccess = (credentialResponse) => {
    try {
      const decoded = jwtDecode(credentialResponse.credential);
      setUser(decoded);
      // Pre-fill name from Google profile
      setReviewData(prev => ({
        ...prev,
        name: decoded.name || ""
      }));
      console.log("Google Auth Success:", decoded);
      
      // Close the Google login and open review dialog
      setShowGoogleLogin(false);
      setReviewDialogOpen(true);
    } catch (error) {
      console.error("Error decoding token:", error);
      alert("Authentication failed. Please try again.");
    }
  };

  // Google Auth Error Handler
  const handleGoogleError = () => {
    console.log("Google Auth Failed");
    setShowGoogleLogin(false);
    alert("Google authentication failed. Please try again.");
  };

  // Handle Review Dialog Close
  const handleReviewDialogClose = () => {
    setReviewDialogOpen(false);
    // Reset review data but keep user authenticated
    setReviewData(prev => ({
      ...prev,
      photo: null,
      photoPreview: null,
      rating: 0,
      comment: "",
      // Keep name from user profile
      name: user ? user.name || "" : ""
    }));
  };

  // Handle Photo Upload
  const handlePhotoUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      // Check file type and size
      if (!file.type.startsWith('image/')) {
        alert('Please upload an image file');
        return;
      }
      if (file.size > 5 * 1024 * 1024) { // 5MB limit
        alert('Please upload an image smaller than 5MB');
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        setReviewData(prev => ({
          ...prev,
          photo: file,
          photoPreview: e.target.result
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  // Remove uploaded photo
  const handleRemovePhoto = () => {
    setReviewData(prev => ({
      ...prev,
      photo: null,
      photoPreview: null
    }));
  };

  // Handle Review Submission
  const handleReviewSubmit = () => {
    if (reviewData.rating === 0) {
      alert("Please provide a rating");
      return;
    }
    if (!reviewData.name.trim()) {
      alert("Please enter your name");
      return;
    }

    // Create FormData for file upload
    const formData = new FormData();
    formData.append('name', reviewData.name);
    formData.append('rating', reviewData.rating);
    formData.append('comment', reviewData.comment);
    if (reviewData.photo) {
      formData.append('photo', reviewData.photo);
    }

    console.log("Review submitted:", {
      name: reviewData.name,
      rating: reviewData.rating,
      comment: reviewData.comment,
      photo: reviewData.photo ? reviewData.photo.name : 'No photo',
      user: user?.email
    });

    // Here you would typically send formData to your backend
    // await fetch('/api/reviews', { method: 'POST', body: formData });

    handleReviewDialogClose();
    alert("Thank you for your review!");
  };

  const handleInputChange = (field, value) => {
    setReviewData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const drawerContent = (
    <Box
      sx={{
        width: 280,
        height: "100%",
        background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        backdropFilter: "blur(10px)",
        color: "white",
        padding: 2,
      }}
    >
      <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 3 }}>
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <FaTableTennis className="text-orange-500 text-2xl" />
          <span className="font-in font-bold text-white">BT's TT Academy</span>
        </Box>
        <IconButton onClick={handleDrawerToggle} sx={{ color: "white" }}>
          <Close />
        </IconButton>
      </Box>

      <List>
        {menuItems.map((item, index) => (
          <ListItem
            key={item}
            component="button"
            onClick={() => handleMobileMenuItemClick(index)}
            sx={{
              border: currentTab === index ? "1px solid #FF9800" : "1px solid rgba(255,255,255,0.1)",
              borderRadius: "8px",
              marginBottom: 1,
              background: currentTab === index ? "rgba(255,165,0,0.2)" : "rgba(255,255,255,0.05)",
              backdropFilter: "blur(10px)",
              transition: "all 0.3s ease",
              "&:hover": {
                background: "rgba(255,165,0,0.2)",
                borderColor: "rgba(255,165,0,0.5)",
              },
            }}
          >
            <ListItemText 
              primary={item} 
              sx={{ 
                color: currentTab === index ? "#FF9800" : "white",
                "& .MuiListItemText-primary": {
                  fontFamily: "'AlanSans', sans-serif",
                  fontWeight: currentTab === index ? 600 : 500,
                }
              }} 
            />
          </ListItem>
        ))}
      </List>

      <Box sx={{ padding: 2 }}>
        <CustomButton 
          onClick={handleAddReviewClick}
          fullWidth
          text={user ? "Add Review" : "Sign In to Add Review"}
        />
          
        
        
        {/* Hidden Google Login that appears when user clicks Add Review */}
        {showGoogleLogin && (
          <Box sx={{ mt: 2 }}>
            <GoogleLogin
              onSuccess={handleGoogleSuccess}
              onError={handleGoogleError}
              theme="filled_black"
              size="medium"
              width="100%"
              text="signin_with"
            />
          </Box>
        )}
      </Box>
    </Box>
  );

  return (
    <>
      <div 
        position="static" 
        sx={{ 
          background: "transparent", 
          boxShadow: "none",
          backdropFilter: "blur(10px)",
          background: "rgba(0,0,0,0.1)",
        }}
      >
        <Toolbar sx={{ justifyContent: "space-between", padding: "8px 0" }}>
          {/* Logo */}
          <Box sx={{ display: "flex", alignItems: "center" }}>
            <FaTableTennis className="text-white text-3xl" />
          </Box>

          {/* Desktop Menu with Tabs */}
          <Box sx={{ display: { xs: "none", md: "flex" }, alignItems: "center", gap: 2 }}>
            <Box 
              sx={{ 
                background: "rgba(0,0,0,0.1)",
                backdropFilter: "blur(10px)",
                borderRadius: "25px",
                border: "1px solid rgba(255,255,255,0.1)",
                padding: "4px",
              }}
            >
              <Tabs
                value={currentTab}
                onChange={handleTabChange}
                sx={{
                  minHeight: "40px",
                  "& .MuiTabs-indicator": {
                    backgroundColor: "#f97316",
                    height: "100%",
                    borderRadius: "20px",
                    boxShadow: "0 2px 8px rgba(255,152,0,0.3)",
                  },
                  "& .MuiTab-root": {
                    color: "rgba(255,255,255,0.7)",
                    fontFamily: "'AlanSans', sans-serif",
                    fontWeight: 500,
                    fontSize: "14px",
                    textTransform: "none",
                    minHeight: "32px",
                    margin: "0 2px",
                    minWidth: "auto",
                    zIndex: 1,
                    transition: "all 0.3s ease",
                    "&.Mui-selected": {
                      color: "white",
                      fontWeight: 600,
                    },
                    "&:hover": {
                      color: "#E2DBD1",
                    },
                  },
                }}
              >
                {menuItems.map((item) => (
                  <Tab key={item} label={item} />
                ))}
              </Tabs>
            </Box>

            {/* Desktop: Custom Add Review Button */}
            <CustomButton  onClick={handleAddReviewClick}/>
              
            
            {/* Hidden Google Login for desktop */}
            {showGoogleLogin && (
              <Box sx={{ position: 'absolute', top: '60px', right: '20px', zIndex: 1000 }}>
                <GoogleLogin
                  onSuccess={handleGoogleSuccess}
                  onError={handleGoogleError}
                  theme="filled_black"
                  size="medium"
                  text="signin_with"
                />
              </Box>
            )}
          </Box>

          {/* Mobile Menu Button */}
          <IconButton
            sx={{ 
              display: { xs: "flex", md: "none" },
              color: "white",
              background: "rgba(0,0,0,0.1)",
              backdropFilter: "blur(10px)",
              border: "1px solid rgba(255,255,255,0.1)",
              "&:hover": {
                background: "rgba(255,165,0,0.2)",
              },
            }}
            onClick={handleDrawerToggle}
          >
            <GiHamburgerMenu />
          </IconButton>
        </Toolbar>
      </div>

      {/* Mobile Drawer */}
      <Drawer
        variant="temporary"
        anchor="right"
        open={drawerOpen}
        onClose={handleDrawerToggle}
        ModalProps={{
          keepMounted: true,
        }}
        sx={{
          display: { xs: "block", md: "none" },
          "& .MuiDrawer-paper": {
            boxSizing: "border-box",
            width: 280,
            border: "none",
            background: "transparent",
          },
        }}
      >
        {drawerContent}
      </Drawer>

      {/* Add Review Dialog - Opens after successful authentication */}
      <Dialog 
        open={reviewDialogOpen} 
        onClose={handleReviewDialogClose}
        maxWidth="sm"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background: "linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)",
            color: "white",
            borderRadius: "12px",
          },
        }}
      >
        <DialogTitle sx={{ borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
          <Typography variant="h6" sx={{ fontFamily: "'AlanSans', sans-serif" }}>
            Add Your Review
          </Typography>
          {user && (
            <Typography variant="body2" sx={{ color: "rgba(255,255,255,0.7)", mt: 0.5 }}>
              Signed in as: {user.name || user.email}
            </Typography>
          )}
        </DialogTitle>
        
        <DialogContent sx={{ padding: 3 }}>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
            {/* Name Field */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Name *
              </Typography>
              <TextField
                fullWidth
                value={reviewData.name}
                onChange={(e) => handleInputChange('name', e.target.value)}
                placeholder="Enter your name"
                variant="outlined"
                disabled={!!user} // Disable if user is authenticated (name comes from Google)
                sx={{
                  "& .MuiOutlinedInput-root": {
                    color: "white",
                    "& fieldset": {
                      borderColor: "rgba(255,255,255,0.2)",
                    },
                    "&:hover fieldset": {
                      borderColor: user ? "rgba(255,255,255,0.2)" : "rgba(255,255,255,0.4)",
                    },
                    "&.Mui-focused fieldset": {
                      borderColor: "#FF9800",
                    },
                    "& .MuiInputBase-input.Mui-disabled": {
                      WebkitTextFillColor: "rgba(255,255,255,0.7)",
                    },
                  },
                }}
              />
              {user && (
                <Typography variant="caption" sx={{ color: "rgba(255,255,255,0.5)", mt: 1, display: 'block' }}>
                  Name is taken from your Google profile
                </Typography>
              )}
            </Box>

            {/* Photo Upload Field */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Photo (Optional)
              </Typography>
              
              {reviewData.photoPreview ? (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                  <Avatar 
                    src={reviewData.photoPreview} 
                    sx={{ width: 80, height: 80, border: '2px solid #FF9800' }}
                  />
                  <Box>
                    <Chip 
                      label={reviewData.photo.name} 
                      variant="outlined" 
                      sx={{ color: 'white', borderColor: 'rgba(255,255,255,0.3)' }}
                    />
                    <Button 
                      onClick={handleRemovePhoto}
                      sx={{ 
                        color: '#FF9800', 
                        ml: 1,
                        '&:hover': { background: 'rgba(255,152,0,0.1)' }
                      }}
                    >
                      Remove
                    </Button>
                  </Box>
                </Box>
              ) : (
                <Box
                  sx={{
                    border: '2px dashed rgba(255,255,255,0.3)',
                    borderRadius: '8px',
                    padding: 3,
                    textAlign: 'center',
                    cursor: 'pointer',
                    transition: 'all 0.3s ease',
                    '&:hover': {
                      borderColor: '#FF9800',
                      background: 'rgba(255,152,0,0.05)',
                    },
                  }}
                  onClick={() => document.getElementById('photo-upload').click()}
                >
                  <input
                    id="photo-upload"
                    type="file"
                    accept="image/*"
                    onChange={handlePhotoUpload}
                    style={{ display: 'none' }}
                  />
                  <FaCloudUploadAlt style={{ fontSize: '2rem', color: '#FF9800', marginBottom: 1 }} />
                  <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                    Click to upload a photo
                  </Typography>
                  <Typography variant="caption" sx={{ color: 'rgba(255,255,255,0.5)' }}>
                    PNG, JPG, JPEG (Max 5MB)
                  </Typography>
                </Box>
              )}
            </Box>

            {/* Rating */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Rating *
              </Typography>
              <Rating
                value={reviewData.rating}
                onChange={(e, newValue) => handleInputChange('rating', newValue)}
                size="large"
                sx={{
                  color: "#FF9800",
                  "& .MuiRating-iconFilled": {
                    color: "#FF9800",
                  },
                }}
              />
            </Box>

            {/* Comment */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Review
              </Typography>
              <TextField
                multiline
                rows={4}
                fullWidth
                value={reviewData.comment}
                onChange={(e) => handleInputChange('comment', e.target.value)}
                placeholder="Share your experience with BT's TT Academy..."
                variant="outlined"
                sx={{
                  "& .MuiOutlinedInput-root": {
                    color: "white",
                    "& fieldset": {
                      borderColor: "rgba(255,255,255,0.2)",
                    },
                    "&:hover fieldset": {
                      borderColor: "rgba(255,255,255,0.4)",
                    },
                    "&.Mui-focused fieldset": {
                      borderColor: "#FF9800",
                    },
                  },
                }}
              />
            </Box>
          </Box>
        </DialogContent>

        <DialogActions sx={{ padding: 3, borderTop: "1px solid rgba(255,255,255,0.1)" }}>
          <Button 
            onClick={handleReviewDialogClose}
            sx={{ 
              color: "rgba(255,255,255,0.7)",
              "&:hover": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Cancel
          </Button>
          <Button 
            onClick={handleReviewSubmit}
            variant="contained"
            disabled={!reviewData.name.trim() || reviewData.rating === 0}
            sx={{
              background: "linear-gradient(45deg, #FF9800 30%, #FF5722 90%)",
              "&:hover:not(:disabled)": {
                background: "linear-gradient(45deg, #E65100 30%, #BF360C 90%)",
              },
              "&:disabled": {
                background: "rgba(255,255,255,0.1)",
                color: "rgba(255,255,255,0.3)",
              },
            }}
          >
            Submit Review
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default NavBar;
